    if not retirement_account:
        return {"result": "others"}
    account_id = retirement_account[0][0]

    # Step 2: Find largest single-stock position in retirement account
    # Single stocks have asset_class='stock'
    positions_query = """
        SELECT p.instrument_id, p.quantity, i.symbol, i.asset_class
        FROM positions p
        JOIN instruments i ON p.instrument_id = i.id
        WHERE p.account_id = ? AND i.asset_class = 'stock'
        ORDER BY p.quantity DESC
    """
    positions = safe_query(final_db_path, positions_query, (account_id,))
    if not positions:
        return {"result": "others"}

    largest_stock_id = positions[0][0]
    largest_stock_qty = positions[0][1]

    # Step 3: Get current synthetic price for the largest stock
    price_query = """
        SELECT synthetic_price
        FROM instrument_quotes
        WHERE instrument_id = ?
        ORDER BY quote_timestamp DESC
        LIMIT 1
    """
    price_result = safe_query(final_db_path, price_query, (largest_stock_id,))
    if not price_result:
        return {"result": "others"}

    current_price = price_result[0][0]
    expected_stop_price = current_price * 0.9

    # Step 4: Check for new stop-loss sell order in final_db
    # Get orders from initial_db for this account/instrument
    initial_orders_query = """
        SELECT id FROM orders
        WHERE account_id = ? AND instrument_id = ? AND side = 'sell' AND order_type = 'stop_loss'
    """
    initial_orders = safe_query(initial_db_path, initial_orders_query, (account_id, largest_stock_id))
    initial_order_ids = {row[0] for row in initial_orders}

    # Get orders from final_db
    final_orders_query = """
        SELECT id, quantity, stop_price, status, time_in_force
        FROM orders
        WHERE account_id = ? AND instrument_id = ? AND side = 'sell' AND order_type = 'stop_loss'
    """
    final_orders = safe_query(final_db_path, final_orders_query, (account_id, largest_stock_id))

    # Find new orders (those not in initial_db)
    new_orders = [order for order in final_orders if order[0] not in initial_order_ids]

    if not new_orders:
        return {"result": "others"}

    # Step 5: Verify the new order meets all requirements
    order_found = False
    for order in new_orders:
        order_id, quantity, stop_price, status, tif = order

        # Check quantity matches position quantity
        if abs(quantity - largest_stock_qty) > 0.01:
            continue

        # Check stop price is approximately 10% below current price (allow small floating point difference)
        if stop_price is None or abs(stop_price - expected_stop_price) > 0.01:
            continue

        # Order meets all criteria
        order_found = True
        break

    if not order_found:
        return {"result": "others"}

