def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re
    from datetime import datetime

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Step 1: Find charger_id for serial_number 'GF-DCFAST-077'
    charger_query = "SELECT id, firmware_version FROM chargers WHERE serial_number = ?"
    initial_charger = safe_query(initial_db_path, charger_query, ('GF-DCFAST-077',))
    final_charger = safe_query(final_db_path, charger_query, ('GF-DCFAST-077',))

    if not initial_charger or not final_charger:
        return {"result": "others"}

    charger_id = initial_charger[0][0]
    initial_firmware = initial_charger[0][1]
    final_firmware = final_charger[0][1]

    # Step 2: Check firmware_version was updated to '3.4.0'
    if final_firmware != '3.4.0':
        return {"result": "others"}

    # Step 3: Get maintenance_events for this charger
    event_query = "SELECT id, event_type, scheduled_time, outcome_status, target_firmware_version FROM maintenance_events WHERE charger_id = ?"
    initial_events = safe_query(initial_db_path, event_query, (charger_id,))
    final_events = safe_query(final_db_path, event_query, (charger_id,))

    if len(final_events) <= len(initial_events):
        return {"result": "others"}

    # Step 4: Find new events (in final but not in initial)
    initial_event_ids = {evt[0] for evt in initial_events}
    new_events = [evt for evt in final_events if evt[0] not in initial_event_ids]

    if not new_events:
        return {"result": "others"}

    # Step 5: Check if any new event matches our requirements
    for event in new_events:
        event_id, event_type, scheduled_time, outcome_status, target_firmware = event

        # Check event_type
        if event_type != 'firmware_update':
            continue

        # Check target_firmware_version
        if target_firmware != '3.4.0':
            continue

        # Check outcome_status is success or completed
        if outcome_status not in ('success', 'completed'):
            continue

        # Check scheduled_time is a Monday at 02:00
        if not scheduled_time:
            continue

        try:
            # Parse the scheduled_time
            dt = datetime.fromisoformat(scheduled_time.replace('Z', '+00:00'))

            # Check if it's Monday (weekday() == 0)
            if dt.weekday() != 0:
                continue

            # Check if time is 02:00
            if dt.hour != 2 or dt.minute != 0:
                continue

            # All checks passed for this event
            return {"result": "complete"}
        except Exception:
            continue

    return {"result": "others"}

