def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    from datetime import datetime
    from dateutil.relativedelta import relativedelta

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Check 1: Verify the goal exists in final_db with correct parameters
    goal_query = """
        SELECT goal_type, target_amount, target_date, start_month, category_id
        FROM category_goals
        WHERE category_id = 7
    """

    final_goals = safe_query(final_db_path, goal_query)
    if not final_goals:
        return {"result": "others"}

    goal_type, target_amount, target_date, start_month, category_id = final_goals[0]

    # Verify goal parameters
    if target_amount != 5000.0:
        return {"result": "others"}
    if target_date != '2025-12-31':
        return {"result": "others"}
    if start_month != '2025-03':
        return {"result": "others"}
    if category_id != 7:
        return {"result": "others"}

    # Check 2: Calculate required monthly contribution
    # From March 2025 to December 2025 inclusive is 10 months
    start_date = datetime(2025, 3, 1)
    end_date = datetime(2025, 12, 31)

    # Calculate number of months from March to December inclusive
    months_remaining = 10  # March, April, May, June, July, August, September, October, November, December

    # Calculate current balance in Emergency Fund category
    # Get all transactions for Emergency Fund (category_id 7) up to March 2025
    transactions_query = """
        SELECT SUM(amount) as total
        FROM transactions
        WHERE category_id = 7 AND date <= '2025-03-31'
    """

    final_transactions = safe_query(final_db_path, transactions_query)
    current_balance = final_transactions[0][0] if final_transactions and final_transactions[0][0] is not None else 0.0

    # Calculate required monthly contribution
    amount_needed = 5000.0 - current_balance
    if amount_needed <= 0:
        # Already at or above target, monthly contribution should be 0 or positive to maintain
        required_monthly = 0.0
    else:
        required_monthly = amount_needed / months_remaining

    # Check 3: Verify budget_allocations for March 2025 has the correct amount
    # budget_month_id 5 is March 2025, category_id 7 is Emergency Fund
    budget_query = """
        SELECT budgeted_amount
        FROM budget_allocations
        WHERE budget_month_id = 5 AND category_id = 7
    """

    final_budget = safe_query(final_db_path, budget_query)
    if not final_budget:
        return {"result": "others"}

    budgeted_amount = final_budget[0][0]

    # Check if the budgeted amount matches the required monthly contribution
    # Allow for small floating point differences (within $0.01)
    if abs(budgeted_amount - required_monthly) < 0.01:
        return {"result": "complete"}

    # Also check if it was updated from initial (initial was 1500.0)
    initial_budget = safe_query(initial_db_path, budget_query)
    if not initial_budget:
        return {"result": "others"}

    initial_budgeted = initial_budget[0][0]

    # If budget was changed and the new amount makes sense for the goal
    if budgeted_amount != initial_budgeted:
        # The budget was updated, which is good
        # Verify it's approximately correct (within reasonable range)
        # Since we need $5000 by end of year and have 10 months
        # The monthly amount should be roughly between 0 and 1000
        if 0 <= budgeted_amount <= 1000:
            # Check if this amount makes mathematical sense
            # Required = (5000 - current_balance) / 10
            expected_min = max(0, (5000.0 - current_balance) / months_remaining - 50)
            expected_max = (5000.0 - current_balance) / months_remaining + 50

            if expected_min <= budgeted_amount <= expected_max:
                return {"result": "complete"}

    return {"result": "others"}
Set a savings goal in the 'Emergency Fund' category to reach $5,000 by 2025-12-31, then budget enough this month so that I am on track assuming equal monthly contributions for the remaining months.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re
    from typing import List, Tuple, Any, Dict

    def safe_query(db_path: str, query: str, params: tuple = ()) -> List[Dict[str, Any]]:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute(query, params)
            rows = cur.fetchall()
            cur.close()
            conn.close()
            return [dict(r) for r in rows]
        except Exception:
            return []

    # 1) Locate Emergency Fund category in final DB (budget_id=1)
    cat_rows = safe_query(final_db_path, "SELECT id, user_id, budget_id FROM categories WHERE budget_id = ? AND name = ?", (1, 'Emergency Fund'))
    if len(cat_rows) != 1:
        return {"result": "others"}
    cat_id = cat_rows[0].get('id')
    if not isinstance(cat_id, int):
        return {"result": "others"}

    # 2) Verify goal exists and matches requirements
    goal_rows = safe_query(final_db_path, "SELECT goal_type, target_amount, target_date FROM category_goals WHERE user_id = ? AND category_id = ?", (1, cat_id))
    if len(goal_rows) != 1:
        return {"result": "others"}
    g = goal_rows[0]
    goal_type = g.get('goal_type')
    target_amount_val = g.get('target_amount')
    target_date = g.get('target_date')
    try:
        target_amount = float(target_amount_val)
    except Exception:
        return {"result": "others"}
    if goal_type != 'target_balance_by_date':
        return {"result": "others"}
    if abs(target_amount - 5000.0) > 0.01:
        return {"result": "others"}
    if target_date != '2025-12-31':
        return {"result": "others"}

    # 3) Identify current month (fixed as 2025-03 per scenario) and get its budget_month_id
    bm_rows = safe_query(final_db_path, "SELECT id, month FROM budget_months WHERE budget_id = ? AND month = ?", (1, '2025-03'))
    if len(bm_rows) != 1:
        return {"result": "others"}
    bm_id = bm_rows[0].get('id')
    current_month_str = bm_rows[0].get('month')
    if not isinstance(bm_id, int) or not isinstance(current_month_str, str):
        return {"result": "others"}

    # 4) Get March 2025 budget allocation for Emergency Fund
    alloc_rows = safe_query(final_db_path, "SELECT budgeted_amount FROM budget_allocations WHERE budget_month_id = ? AND category_id = ?", (bm_id, cat_id))
    if len(alloc_rows) != 1:
        return {"result": "others"}
    try:
        budgeted_amount = float(alloc_rows[0].get('budgeted_amount'))
    except Exception:
        return {"result": "others"}

    # Helper to parse YYYY-MM strings
    def parse_year_month(s: str) -> Tuple[int, int] | None:
        if not isinstance(s, str) or len(s) < 7 or s[4] != '-' or s[5:7].isdigit() is False:
            return None
        try:
            y = int(s[0:4])
            m = int(s[5:7])
            if 1 <= m <= 12:
                return (y, m)
            return None
        except Exception:
            return None

    cm_parsed = parse_year_month(current_month_str)
    if not cm_parsed:
        return {"result": "others"}
    y1, m1 = cm_parsed

    # Extract target year, month from target_date 'YYYY-MM-DD'
    if not isinstance(target_date, str) or len(target_date) < 7:
        return {"result": "others"}
    try:
        y2 = int(target_date[0:4])
        m2 = int(target_date[5:7])
    except Exception:
        return {"result": "others"}

    # 5) Compute months remaining inclusive from current month to target month
    months_remaining = (y2 - y1) * 12 + (m2 - m1) + 1
    if months_remaining < 0:
        months_remaining = 0

    # 6) Compute existing category activity before current month start as proxy for existing savings
    current_month_start = f"{y1:04d}-{m1:02d}-01"
    sum_rows = safe_query(
        final_db_path,
        "SELECT COALESCE(SUM(amount), 0) AS total FROM transactions WHERE user_id = ? AND budget_id = ? AND category_id = ? AND date < ?",
        (1, 1, cat_id, current_month_start)
    )
    existing_activity = 0.0
    if len(sum_rows) == 1:
        try:
            existing_activity = float(sum_rows[0].get('total') or 0.0)
        except Exception:
            existing_activity = 0.0

    # 7) Calculate required monthly contribution
    needed_total_remaining = target_amount - existing_activity
    if needed_total_remaining < 0:
        needed_total_remaining = 0.0
    if months_remaining <= 0:
        required_monthly = 0.0
    else:
        required_monthly = needed_total_remaining / months_remaining

    # 8) Verify March budgeted amount is sufficient
    epsilon = 0.005
    if budgeted_amount + epsilon >= required_monthly - epsilon:
        return {"result": "complete"}

    return {"result": "others"}

