 by=collections.defaultdict(list)
 for x in rows:by[x['traj_uid']].append(x)
 hist=collections.Counter(len(v) for v in by.values());print('lens',hist)
 # actions extract
 acts=collections.Counter();
 for x in rows:
  out=x.get('output','')
  if 'list_tools' in out: acts['list_tools']+=1
  elif 'call_tool' in out: 
   m=re.search(r'"tool_name"\s*:\s*"([^"]+)',out);acts['call:'+ (m.group(1) if m else '?')]+=1
