 print('acts',acts.most_common(12))
 for uid,vs in list(by.items())[:3]:
  print('traj',len(vs),'scores',[v.get('score') for v in vs], 'valid',[v.get('is_action_valid') for v in vs])
  for v in vs: print('  ',v['step_num'],v['output'][:180].replace('\n',' '))
