'''
    prefix += textwrap.indent(textwrap.dedent(imports).strip()+'\n','    ') if imports else ''
    prefix += '''
    def query(path, sql, params=()):
        # A failed read is not evidence of an empty initial state.
        with closing(sqlite3.connect(f"file:{path}?mode=ro", uri=True)) as conn:
            return conn.execute(sql, params).fetchall()

    try:
'''
