    if watchlist_id in initial_ids:
        continue
    symbols = query(final_db_path, """SELECT s.symbol FROM watchlist_items wi
        JOIN securities s ON s.id = wi.security_id WHERE wi.watchlist_id = ?""", (watchlist_id,))
